//! Cargo-driven `libtiff.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x73130000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fefc000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fefc000000u64)),
        o => panic!("libtiff-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:zlib", "engine:c:getopt", "engine:pseh", "import:libjpeg", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames", "body"],
        "x86_64" => &["engine:c:zlib", "engine:c:getopt", "engine:pseh", "import:libjpeg", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames", "body"],
        "aarch64" => &["engine:c:zlib", "engine:c:getopt", "engine:pseh", "import:libjpeg", "import:user32", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames", "body"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("libtiff_shims", &["vendor/libtiff/tif_aux.c", "vendor/libtiff/tif_close.c", "vendor/libtiff/tif_codec.c", "vendor/libtiff/tif_color.c", "vendor/libtiff/tif_compress.c", "vendor/libtiff/tif_dir.c", "vendor/libtiff/tif_dirinfo.c", "vendor/libtiff/tif_dirread.c", "vendor/libtiff/tif_dirwrite.c", "vendor/libtiff/tif_dumpmode.c", "vendor/libtiff/tif_error.c", "vendor/libtiff/tif_extension.c", "vendor/libtiff/tif_fax3.c", "vendor/libtiff/tif_fax3sm.c", "vendor/libtiff/tif_flush.c", "vendor/libtiff/tif_getimage.c", "vendor/libtiff/tif_hash_set.c", "vendor/libtiff/tif_luv.c", "vendor/libtiff/tif_lzw.c", "vendor/libtiff/tif_next.c", "vendor/libtiff/tif_open.c", "vendor/libtiff/tif_packbits.c", "vendor/libtiff/tif_pixarlog.c", "vendor/libtiff/tif_predict.c", "vendor/libtiff/tif_print.c", "vendor/libtiff/tif_read.c", "vendor/libtiff/tif_strip.c", "vendor/libtiff/tif_swab.c", "vendor/libtiff/tif_thunder.c", "vendor/libtiff/tif_tile.c", "vendor/libtiff/tif_version.c", "vendor/libtiff/tif_warning.c", "vendor/libtiff/tif_win32.c", "vendor/libtiff/tif_write.c", "vendor/libtiff/tif_zip.c"])
        .whole_c_objects("libtiff_shims")
        .spec2def("vendor/libtiff/libtiff.spec", "libtiff.dll")
        .import_lib("vendor/libjpeg/libjpeg.spec", "libjpeg.dll", "libjpeg")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
